# 72_tables_random.R: Figure 5 random-split summaries from 71_fit_random.R (no refitting). One fit per split (no seed averaging).
# Summaries across the 30 splits: median and central 95% interval (2.5% and 97.5% quantiles, type 7); min/max, mean. Intervals describe split-to-split variability,
# NOT formal significance tests (splits share sites, so they are not independent). Negative values are retained. Run from final/.
suppressMessages(library(dplyr)); OUT <- "revision_random/tables"; q <- function(x, p) if (all(!is.finite(x))) NA_real_ else unname(quantile(x[is.finite(x)], p, type = 7))
MODEL_LAB <- c(spread_only = "Spread only", linear_const = "Spread + linear position", nonlinear_const = "Spread + nonlinear position")
summ <- function(d, v) d |> summarise(median = median(.data[[v]], na.rm = TRUE), q025 = q(.data[[v]], .025), q975 = q(.data[[v]], .975), min = min(.data[[v]], na.rm = TRUE), max = max(.data[[v]], na.rm = TRUE), mean = mean(.data[[v]], na.rm = TRUE), n_splits = sum(is.finite(.data[[v]])), .groups = "drop")
for (pool in c("shared", "full")) { V <- read.csv(file.path(OUT, sprintf("rv5_validation_splits_%s.csv", pool)), stringsAsFactors = FALSE); I <- read.csv(file.path(OUT, sprintf("rv5_importance_splits_%s.csv", pool)), stringsAsFactors = FALSE)
  key <- c("community", "pool", "order", "response"); V$transform <- "log10"; I$transform <- "log10"; key2 <- c(key, "transform")
  W <- V |> select(all_of(key2), split, model, D2_heldout) |> tidyr::pivot_wider(names_from = model, values_from = D2_heldout)
  P <- W |> transmute(across(all_of(key2)), split, delta_linear_vs_spread = linear_const - spread_only, delta_nonlinear_vs_spread = nonlinear_const - spread_only, delta_nonlinear_vs_linear = nonlinear_const - linear_const, D2_spread_only = spread_only, D2_linear = linear_const, D2_nonlinear = nonlinear_const)
  Pl <- P |> tidyr::pivot_longer(starts_with("delta_"), names_to = "contrast", values_to = "delta_D2"); write.csv(Pl, file.path(OUT, sprintf("rv5_paired_splits_%s.csv", pool)), row.names = FALSE)
  Ps <- Pl |> group_by(across(all_of(key2)), contrast) |> summ("delta_D2") |> left_join(Pl |> group_by(across(all_of(key2)), contrast) |> summarise(n_splits_positive = sum(delta_D2 > 0, na.rm = TRUE), .groups = "drop"), by = c(key2, "contrast")); write.csv(Ps, file.path(OUT, sprintf("rv5_paired_summary_%s.csv", pool)), row.names = FALSE)
  Pf <- V |> group_by(across(all_of(key2)), model) |> summ("D2_heldout") |> mutate(model_label = MODEL_LAB[model]) |> left_join(V |> group_by(across(all_of(key2)), model) |> summarise(train_mean = mean(D2_train, na.rm = TRUE), train_median = median(D2_train, na.rm = TRUE), .groups = "drop") |> mutate(across(starts_with("train"), ~ ifelse(is.nan(.), NA, .))), by = c(key2, "model")); write.csv(Pf, file.path(OUT, sprintf("rv5_performance_%s.csv", pool)), row.names = FALSE)
  Cv <- V |> filter(model != "spread_only") |> group_by(across(all_of(key2)), model) |> summarise(n_fits = n(), n_converged = sum(converged %in% TRUE), prop_converged = mean(converged %in% TRUE), n_with_warnings = sum(n_warnings > 0), n_failed = sum(!is.finite(D2_heldout)), .groups = "drop"); write.csv(Cv, file.path(OUT, sprintf("rv5_convergence_%s.csv", pool)), row.names = FALSE)
  # spread-only comparator: failed/NA counts and warnings
  Ik <- c(key2, "model"); Ia <- I |> group_by(across(all_of(c(Ik, "predictor", "component")))) |> summ("absolute") |> rename(abs_median = median, abs_q025 = q025, abs_q975 = q975, abs_min = min, abs_max = max, abs_mean = mean) |>
    left_join(I |> group_by(across(all_of(c(Ik, "predictor", "component")))) |> summarise(heldout_D2_median = median(D2_heldout), heldout_D2_mean = mean(D2_heldout), n_splits_negative = sum(absolute < 0, na.rm = TRUE), .groups = "drop"), by = c(Ik, "predictor", "component")) |>
    mutate(relative_share = ifelse(heldout_D2_median > 0, abs_median / heldout_D2_median, NA_real_), relative_flag = case_when(heldout_D2_median <= 0 ~ "undefined (median held-out D2 <= 0)", heldout_D2_median < .02 ~ "unstable (median held-out D2 < 0.02)", TRUE ~ "ok"))
  write.csv(I |> select(community, pool, order, response, model, split, predictor, component, absolute, D2_heldout), file.path(OUT, sprintf("rv5_importance_split_values_%s.csv", pool)), row.names = FALSE); write.csv(Ia, file.path(OUT, sprintf("rv5_importance_summary_%s.csv", pool)), row.names = FALSE)
  cat("== ", pool, "\n"); print(as.data.frame(Ps |> filter(contrast != "delta_nonlinear_vs_linear") |> group_by(community, response, contrast) |> summarise(across(c(median), list(range = ~ sprintf("%.3f..%.3f", min(.), max(.)))), pos = paste(n_splits_positive, collapse = ","), .groups = "drop")))
  cat("importance columns check: dup rows ", anyDuplicated(Ia[c(Ik, "predictor", "component")]), " n_splits range ", range(Ia$n_splits), "\n") }
